    assert_selector "#maybe .card", wait: 10
    # Wait for custom columns frames to load (they have turbo-frames)
    # Find first custom column id
    column = columns(:writebook_in_progress)
    column_id = "column_#{column.id}"
    # Wait for column frame to load its list
    assert_selector "##{column_id}", wait: 10
    # The list inside frame may take a moment
    assert_selector "##{column_id} .cards__list", wait: 10

    # Get initial card from Maybe
    maybe_card = find("#maybe .card", match: :first)
    maybe_card_id = maybe_card["id"]
    puts "Dragging card #{maybe_card_id} from Maybe to #{column_id}"

    # Simulate drag via JS and check instant behavior + classes
    result = page.evaluate_script(<<~JS)
      (() => {
        const card = document.querySelector("#maybe .card");
        const dest = document.querySelector("##{column_id}");
        if (!card || !dest) return { error: "missing elements", card: !!card, dest: !!dest };

        const dataTransfer = new DataTransfer();

        // dragstart should dim card
        card.dispatchEvent(new DragEvent("dragstart", { bubbles: true, cancelable: true, dataTransfer }));
        const draggedHasClass = card.classList.contains("drag-and-drop__dragged-item");

        // dragover should highlight column
        const list = dest.querySelector(".cards__list") || dest;
        // dispatch on dest column itself to ensure closest finds it
        dest.dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer }));
        const hoverHasClass = dest.classList.contains("drag-and-drop__hover-container");

        // drop should move instantly (synchronously)
        dest.dispatchEvent(new DragEvent("drop", { bubbles: true, cancelable: true, dataTransfer }));
        const movedSynchronously = dest.contains(card);

        card.dispatchEvent(new DragEvent("dragend", { bubbles: true, cancelable: true, dataTransfer }));
        const draggedCleaned = !card.classList.contains("drag-and-drop__dragged-item");
        const hoverCleaned = !dest.classList.contains("drag-and-drop__hover-container");

        return {
          draggedHasClass,
          hoverHasClass,
          movedSynchronously,
          draggedCleaned,
          hoverCleaned,
          cardParentId: card.closest(".cards")?.id
        };
      })()
    JS

    puts "Drag result: #{result.inspect}"
    assert result["draggedHasClass"], "dragged card should dim with dragged-item class"
    assert result["hoverHasClass"], "hover column should light up with hover-container class"
    assert result["movedSynchronously"], "card should move to destination synchronously on drop"
    assert_equal column_id, result["cardParentId"], "card should be inside destination column"
    assert result["draggedCleaned"], "dragged class should be cleaned after dragend"
    assert result["hoverCleaned"], "hover class should be cleaned after drop"

