        // Count fetch calls
        let fetchCount = 0;
        const origFetch = window.fetch;
        window.fetch = (...args) => {
          const url = args[0]?.toString() || "";
          if (url.includes("/triage") || url.includes("/not_now") || url.includes("/closure")) fetchCount++;
          return origFetch(...args);
        };

